context_details.context_postfix:
0.0 /result.total_adjustments xdef
"ADJUSTMENTS TO INCOME (Schedule 1 Part II)" job.audit_trail swap addto
{ /Calculate_AGI_Adjustments executetable } job.taxpayers forall
{ /Calculate_Educator_Expenses executetable } job.taxpayers forall
Calculate_OBBBA_Deductions
Calculate_IRA_Deduction          { Schedule 1 Line 20 - IRA deduction per Publication 590-A, IRC 219 }
Calculate_HSA_Deduction          { Schedule 1 Line 13 - HSA deduction per Form 8889, IRC 223 }
Calculate_Student_Loan_Deduction { Schedule 1 Line 21 - Student loan interest per Publication 970, IRC 221 }
result.total_obbba_deductions result.ira_deduction f+ result.hsa_deduction f+ result.student_loan_deduction f+ result.educator_expense_deduction f+ result.total_adjustments f+ /result.total_adjustments xdef

result.agi salt_phaseout_start f<= {
  salt_cap /effective_salt_cap local
} {
  result.agi salt_phaseout_end f>= {
    salt_reduced_cap /effective_salt_cap local
  } {
    result.agi salt_phaseout_start f- salt_phaseout_rate f*
    salt_cap swap f- salt_reduced_cap fmax /effective_salt_cap local
  } ifelse
} ifelse

action_details.action_postfix:
0.10 /parent_marginal_rate local
result.agi bracket_1_mfj <={
  0.10 /parent_marginal_rate local
} if
result.agi bracket_1_mfj > result.agi bracket_2_mfj <=and {
  0.12 /parent_marginal_rate local
} if
result.agi bracket_2_mfj > result.agi bracket_3_mfj <=and {
  0.22 /parent_marginal_rate local
} if
result.agi bracket_3_mfj > result.agi bracket_4_mfj <=and {
  0.24 /parent_marginal_rate local
} if
result.agi bracket_4_mfj > result.agi bracket_5_mfj <=and {
  0.32 /parent_marginal_rate local
} if
result.agi bracket_5_mfj > result.agi bracket_6_mfj <=and {
  0.35 /parent_marginal_rate local
} if
result.agi bracket_6_mfj > {
  0.37 /parent_marginal_rate local
} if
net_unearned_income parent_marginal_rate f* /dependent.kiddie_tax_amount xdef
"    Parent's marginal tax rate: " parent_marginal_rate 100 f* cvs strconcat "%" strconcat job.audit_trail swap addto
"    Kiddie tax amount: $" dependent.kiddie_tax_amount cvs strconcat job.audit_trail swap addto

0.0 /taxpayer.moving_expense_deduction xdef

taxpayer.is_military true eq {
  "  " taxpayer.name strconcat " - Military move but does not meet distance test" strconcat job.audit_trail swap addto
} if
